import numpy as np
import matplotlib.pyplot as plt
import argparse
import json
import os
from pathlib import Path


def compare_sparseness(initial_scores, optimized_scores, labels=None, output_dir=None):
    """
    Compare sparseness scores between initial and optimized LRP explanations.
    
    Args:
        initial_scores: List of initial sparseness scores
        optimized_scores: List of optimized sparseness scores
        labels: Optional list of labels for each example
        output_dir: Directory to save results (if None, just display)
    """
    # Convert inputs to numpy arrays
    initial = np.array(initial_scores)
    optimized = np.array(optimized_scores)
    
    # Calculate statistics
    avg_initial = np.mean(initial)
    avg_optimized = np.mean(optimized)
    improvement = avg_optimized - avg_initial
    percent_improvement = (improvement / avg_initial) * 100 if avg_initial > 0 else float('inf')
    
    # Create a results dictionary
    results = {
        "avg_initial_sparseness": avg_initial,
        "avg_optimized_sparseness": avg_optimized,
        "absolute_improvement": improvement,
        "percent_improvement": percent_improvement,
        "num_examples": len(initial),
        "improved_examples": np.sum(optimized > initial),
        "worsened_examples": np.sum(optimized < initial),
        "unchanged_examples": np.sum(optimized == initial),
    }
    
    # Display results
    print("\n===== Sparseness Comparison =====")
    print(f"Average initial sparseness: {avg_initial:.4f}")
    print(f"Average optimized sparseness: {avg_optimized:.4f}")
    print(f"Absolute improvement: {improvement:.4f}")
    print(f"Percent improvement: {percent_improvement:.2f}%")
    print(f"Number of examples analyzed: {len(initial)}")
    print(f"Number of examples improved: {results['improved_examples']} ({results['improved_examples']/len(initial)*100:.1f}%)")
    print(f"Number of examples worsened: {results['worsened_examples']} ({results['worsened_examples']/len(initial)*100:.1f}%)")
    
    # Create visualizations
    plt.figure(figsize=(15, 10))
    
    # 1. Bar chart comparing average scores
    plt.subplot(2, 2, 1)
    plt.bar(['Initial', 'Optimized'], [avg_initial, avg_optimized], color=['blue', 'red'])
    plt.ylim(0, 1.0)
    plt.title('Average Sparseness Comparison')
    plt.ylabel('Sparseness (0-1)')
    
    # 2. Histogram of improvements
    plt.subplot(2, 2, 2)
    improvements = optimized - initial
    plt.hist(improvements, bins=10, color='green', alpha=0.7)
    plt.axvline(x=0, color='black', linestyle='--')
    plt.title('Distribution of Improvements')
    plt.xlabel('Improvement (optimized - initial)')
    
    # 3. Scatter plot (initial vs optimized)
    plt.subplot(2, 2, 3)
    plt.scatter(initial, optimized, alpha=0.7)
    plt.plot([0, 1], [0, 1], 'k--')  # Diagonal line
    plt.xlim(0, 1)
    plt.ylim(0, 1)
    plt.title('Initial vs. Optimized Scores')
    plt.xlabel('Initial Sparseness')
    plt.ylabel('Optimized Sparseness')
    
    # 4. Per-example comparison
    plt.subplot(2, 2, 4)
    indices = np.arange(len(initial))
    width = 0.35
    plt.bar(indices - width/2, initial, width, label='Initial', color='blue', alpha=0.7)
    plt.bar(indices + width/2, optimized, width, label='Optimized', color='red', alpha=0.7)
    
    if labels:
        plt.xticks(indices, labels, rotation=90)
    else:
        plt.xticks(indices, [f'Ex {i+1}' for i in indices])
    
    plt.ylim(0, 1.0)
    plt.title('Per-Example Comparison')
    plt.ylabel('Sparseness (0-1)')
    plt.legend()
    
    plt.tight_layout()
    
    # Save results if output directory is specified
    if output_dir:
        output_dir = Path(output_dir)
        output_dir.mkdir(exist_ok=True, parents=True)
        
        # Save plot
        plt.savefig(output_dir / 'sparseness_comparison.png', dpi=300)
        
        # Save raw results as JSON
        with open(output_dir / 'sparseness_results.json', 'w') as f:
            json.dump(results, f, indent=2)
            
        # Save detailed results as CSV
        with open(output_dir / 'detailed_results.csv', 'w') as f:
            f.write("example,initial,optimized,improvement\n")
            for i in range(len(initial)):
                example_label = labels[i] if labels else f"Example_{i+1}"
                f.write(f"{example_label},{initial[i]:.6f},{optimized[i]:.6f},{improvements[i]:.6f}\n")
    
    plt.show()
    return results


